<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__,2).'/config/config.php';
function stocktake_json(int $status,array $body):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())stocktake_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();
if(!empty($_SESSION['must_change_password']))stocktake_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$storeRoles=['admin','director','sub_director','headteacher','storekeeper'];$managers=['admin','director','sub_director','headteacher'];
if(!in_array($role,$storeRoles,true))stocktake_json(403,['ok'=>false,'message'=>'Your role cannot access stocktakes.']);
try{$db=db();$school=filter_var($_GET['school_id']??$_POST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)stocktake_json(422,['ok'=>false,'message'=>'Choose a school.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())stocktake_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
if($_SERVER['REQUEST_METHOD']==='GET'){$id=(int)($_GET['id']??0);if($id){$q=$db->prepare('SELECT s.*,u.name created_by_name,r.name reviewed_by_name FROM inventory_stocktakes s JOIN users u ON u.id=s.created_by LEFT JOIN users r ON r.id=s.reviewed_by WHERE s.id=? AND s.school_id=?');$q->execute([$id,$school]);$session=$q->fetch();if(!$session)stocktake_json(404,['ok'=>false,'message'=>'Stocktake not found.']);$q=$db->prepare('SELECT l.id line_id,l.item_id,i.item_name,i.unit,l.snapshot_quantity,l.counted_quantity,l.line_note,i.quantity current_quantity FROM inventory_stocktake_lines l JOIN inventory_items i ON i.id=l.item_id AND i.school_id=l.school_id WHERE l.stocktake_id=? AND l.school_id=? ORDER BY i.item_name');$q->execute([$id,$school]);$session['lines']=$q->fetchAll();$session['can_review']=in_array($role,['admin','director','sub_director','headteacher'],true)&&(int)$session['created_by']!==$uid;stocktake_json(200,['ok'=>true,'data'=>$session]);}$q=$db->prepare('SELECT s.id,s.reference,s.status,s.note,s.created_at,s.reviewed_at,u.name created_by_name,COUNT(l.id) item_count,SUM(l.counted_quantity IS NOT NULL) counted_items FROM inventory_stocktakes s JOIN users u ON u.id=s.created_by LEFT JOIN inventory_stocktake_lines l ON l.stocktake_id=s.id AND l.school_id=s.school_id WHERE s.school_id=? GROUP BY s.id ORDER BY s.created_at DESC LIMIT 50');$q->execute([$school]);stocktake_json(200,['ok'=>true,'data'=>$q->fetchAll()]);}
if($_SERVER['REQUEST_METHOD']!=='POST')stocktake_json(405,['ok'=>false,'message'=>'Method not allowed.']);$token=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'');if(!hash_equals($_SESSION['csrf']??'',$token))stocktake_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
if($action==='create'){$note=trim((string)($_POST['note']??''));if(mb_strlen($note)>1000)throw new DomainException('The note must be 1,000 characters or fewer.');$db->beginTransaction();$q=$db->prepare('SELECT id,quantity FROM inventory_items WHERE school_id=? ORDER BY id FOR UPDATE');$q->execute([$school]);$items=$q->fetchAll();if(!$items)throw new DomainException('Add stock items before starting a stocktake.');$ref='STK-'.date('Ymd-His').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$db->prepare('INSERT INTO inventory_stocktakes(school_id,reference,note,created_by) VALUES(?,?,?,?)');$q->execute([$school,$ref,$note?:null,$uid]);$id=(int)$db->lastInsertId();$line=$db->prepare('INSERT INTO inventory_stocktake_lines(stocktake_id,school_id,item_id,snapshot_quantity) VALUES(?,?,?,?)');foreach($items as $item)$line->execute([$id,$school,$item['id'],$item['quantity']]);stocktake_audit($db,$uid,'create',$id,['school_id'=>$school,'reference'=>$ref,'item_count'=>count($items)]);$db->commit();stocktake_json(201,['ok'=>true,'message'=>'Stocktake started with a snapshot of '.count($items).' items.','data'=>['id'=>$id]]);}
$id=(int)($_POST['stocktake_id']??0);if(!$id)throw new DomainException('Choose a stocktake.');$db->beginTransaction();$q=$db->prepare('SELECT * FROM inventory_stocktakes WHERE id=? AND school_id=? FOR UPDATE');$q->execute([$id,$school]);$s=$q->fetch();if(!$s)throw new DomainException('Stocktake not found in this school.');
if($action==='save_counts'){if(!in_array($s['status'],['draft'],true)||((int)$s['created_by']!==$uid&&!in_array($role,$managers,true)))throw new DomainException('Only the stocktake owner or a school manager can edit a draft.');$counts=$_POST['counts']??[];if(!is_array($counts)||count($counts)>5000)throw new DomainException('Invalid count data.');$q=$db->prepare('SELECT id FROM inventory_stocktake_lines WHERE stocktake_id=? AND school_id=?');$q->execute([$id,$school]);$valid=array_fill_keys(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)),true);$save=$db->prepare('UPDATE inventory_stocktake_lines SET counted_quantity=?,line_note=? WHERE id=? AND stocktake_id=? AND school_id=?');foreach($counts as $lineId=>$row){$lineId=filter_var($lineId,FILTER_VALIDATE_INT);if(!$lineId||!isset($valid[$lineId])||!is_array($row))throw new DomainException('A count line is outside this stocktake.');$raw=trim((string)($row['quantity']??''));$note=trim((string)($row['note']??''));if($raw===''||!is_numeric($raw)||(float)$raw<0||(float)$raw>100000000||!preg_match('/^\d+(?:\.\d{1,2})?$/',$raw)||mb_strlen($note)>255)throw new DomainException('Enter non-negative counts with at most two decimal places and notes up to 255 characters.');$save->execute([(float)$raw,$note?:null,$lineId,$id,$school]);}stocktake_audit($db,$uid,'save_counts',$id,['school_id'=>$school,'lines_saved'=>count($counts)]);$db->commit();stocktake_json(200,['ok'=>true,'message'=>'Counts saved.']);}
if($action==='submit'){if($s['status']!=='draft'||((int)$s['created_by']!==$uid&&!in_array($role,$managers,true)))throw new DomainException('Only the stocktake owner or a school manager can submit a draft.');$q=$db->prepare('SELECT COUNT(*) total,SUM(counted_quantity IS NOT NULL) counted FROM inventory_stocktake_lines WHERE stocktake_id=? AND school_id=?');$q->execute([$id,$school]);$totals=$q->fetch();if((int)$totals['total']===0||(int)$totals['total']!==(int)$totals['counted'])throw new DomainException('Complete every item count before submitting.');$q=$db->prepare('SELECT COUNT(*) FROM inventory_items i WHERE i.school_id=? AND NOT EXISTS(SELECT 1 FROM inventory_stocktake_lines l WHERE l.stocktake_id=? AND l.school_id=i.school_id AND l.item_id=i.id)');$q->execute([$school,$id]);if((int)$q->fetchColumn()>0)throw new DomainException('New stock items were added after this snapshot. Start a new stocktake to include them.');$db->prepare("UPDATE inventory_stocktakes SET status='submitted' WHERE id=? AND school_id=?")->execute([$id,$school]);stocktake_audit($db,$uid,'submit',$id,['school_id'=>$school]);$db->commit();stocktake_json(200,['ok'=>true,'message'=>'Stocktake submitted for independent review.']);}
if($action==='review'){if(!in_array($role,$managers,true))throw new DomainException('Only school managers can review stocktakes.');if((int)$s['created_by']===$uid)throw new DomainException('The stocktake creator cannot review their own count.');if($s['status']!=='submitted')throw new DomainException('Only submitted stocktakes can be reviewed.');$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['review_note']??''));if(!in_array($decision,['apply','reject'],true)||mb_strlen($note)>1000||($decision==='reject'&&$note===''))throw new DomainException('Choose apply or reject; a rejection requires a reason.');if($decision==='reject'){$db->prepare("UPDATE inventory_stocktakes SET status='rejected',review_note=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND status='submitted'")->execute([$note,$uid,$id,$school]);stocktake_audit($db,$uid,'reject',$id,['school_id'=>$school,'note'=>$note]);$db->commit();stocktake_json(200,['ok'=>true,'message'=>'Stocktake rejected with feedback.']);}
$q=$db->prepare('SELECT l.item_id,l.counted_quantity,i.item_name,i.quantity current_quantity,i.last_unit_cost FROM inventory_stocktake_lines l JOIN inventory_items i ON i.id=l.item_id AND i.school_id=l.school_id WHERE l.stocktake_id=? AND l.school_id=? ORDER BY l.item_id FOR UPDATE');$q->execute([$id,$school]);$lines=$q->fetchAll();if(!$lines||count(array_filter($lines,fn($x)=>$x['counted_quantity']===null)))throw new DomainException('All item counts must be complete before applying.');$update=$db->prepare('UPDATE inventory_items SET quantity=?,updated_by=? WHERE id=? AND school_id=?');$movement=$db->prepare("INSERT INTO inventory_movements(school_id,item_id,movement_type,quantity,unit_cost,balance_before,balance_after,note,recorded_by) VALUES(?,?,'adjusted',?,?,?,?,?,?)");foreach($lines as $line){$before=(float)$line['current_quantity'];$after=(float)$line['counted_quantity'];if(abs($before-$after)<0.00001)continue;$update->execute([$after,$uid,$line['item_id'],$school]);$movement->execute([$school,$line['item_id'],$after,$line['last_unit_cost'],$before,$after,'Stocktake '.$s['reference'].($note?' — '.$note:''),$uid]);$movementId=(int)$db->lastInsertId();stocktake_audit($db,$uid,'stocktake_adjustment',$movementId,['school_id'=>$school,'stocktake_id'=>$id,'item_id'=>(int)$line['item_id'],'item_name'=>$line['item_name'],'before'=>$before,'after'=>$after]);}$db->prepare("UPDATE inventory_stocktakes SET status='applied',review_note=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,applied_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND status='submitted'")->execute([$note?:null,$uid,$id,$school]);stocktake_audit($db,$uid,'apply',$id,['school_id'=>$school,'reference'=>$s['reference'],'line_count'=>count($lines)]);$db->commit();stocktake_json(200,['ok'=>true,'message'=>'Stocktake applied. Balance changes and audit history were recorded.']);}
throw new DomainException('Unknown stocktake action.');
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();stocktake_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();error_log('Stocktake request failed: '.$e->getMessage());stocktake_json(500,['ok'=>false,'message'=>'Stocktake could not be completed. Verify that its database migration is installed.']);}
function stocktake_audit(PDO $db,int $uid,string $action,int $entity,array $details):void{$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$action,'inventory_stocktake',$entity,json_encode($details,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);}

